import copy,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
p=json.loads((ROOT/'experiments/task52f_preregistration_v1.json').read_text())
p['task']='52g';p['runtime_budget_seconds']=14400;p['encoder_calibration']['updates']=0
p['arms']=[dict(copy.deepcopy(p['arms'][2]),id=name,recalibrate=False,bptt=512,guard=guard,project=project) for name,guard,project in [('long_control',False,False),('channel_guard',True,False),('gradient_projection',False,True),('combined',True,True)]]
p['preservation']=dict(weight=1.0,denominator_floor=1e-6,block_ticks=128,reference='Frozen original52d trajectory, same fit windows and initial conditions; training-only reference, never an inference component.',formula='mean_channels relu((block_MSE-current_reference_block_MSE)/clamp(reference_block_MSE,1e-6)); block is128ticks and batch-averaged. No penalty for improving a channel.')
p['projection']=dict(priority='current-objective gradient, including guard when enabled',formula='For each independent seed/model: if dot(gc,gv)<0, gv <- gv-dot(gc,gv)/norm(gc)^2*gc; use gc+gv before the original per-model gradient clip and Adam.',limitation='Euclidean first-order gradient protection is not a guarantee for finite Adam steps, individual channels, or autonomous rollouts. Test those explicitly.')
p['objective']='Same52f long-credit data, batches,800updates and original unpenalized validation/selection. Factorial2x2: training-only per-channel regression penalty x current-priority projection of conflicting trajectory gradient. All12models share512tick forward/BPTT. Frozen encoders and same10logical states; no calibration warmup.'
p['diagnostics']='Per-checkpoint original channel/V/Ca guards; gradient conflict frequency/cosine before-after, penalty activation perchannel, gradient norms, matched control. Early andlate budgets fromsame trajectory. No final evaluation of rejected checkpoints and no promotion by mean loss.'
p['limitations']='Exploratory reused52panel, not independent confirmation. Both interventions are training-only heuristics, not guarantees. No new state dimensions, inputs or analytic online gates. Adam may still regress despite first-order projection. Same inference architecture; timing differences among identical selected fallback models are not architecture speedups. Cap52j; no automaticTask53.'
(ROOT/'experiments/task52g_preregistration_v1.json').write_text(json.dumps(p,indent=2)+'\n')
facts=json.loads((ROOT/'experiments/results/task52f_audit_v1/audit.json').read_text())
h=dict(task='52g',source='52f',facts=dict(finite=facts['finite_parameters_independently_verified'],all_fallback=facts['all_selected_fallback'],last={k:v['last'] for k,v in facts['arms'].items()}),hypotheses=[dict(id='preservation',claim='A missing per-channel training penalty permits compensated current regressions despite better V/Ca.',test='guard vs control andcombined vs projection',falsifier='Penalty activates but original per-channel nonregression andeligible checkpoints do not improve.'),dict(id='conflict',claim='Conflicting trajectory gradients overwrite useful current gradients.',test='projection vs control andcombined vs guard; measure dot products',falsifier='Conflicts are corrected but no improvement in original guards, or there are few conflicts.'),dict(id='interaction',claim='Current-level penalty andgradient priority together retain long-credit benefits.',test='2x2 difference of differences on originaldevelopment errors andeligible seed-checkpoints',falsifier='Combined loses V/Ca benefit or cannot reduce current regressions relative to both single interventions.')],user_cap='Do not go beyond52j; no thresholds or abstraction changes.')
(ROOT/'experiments/task52g_hypotheses_v1.json').write_text(json.dumps(h,indent=2)+'\n')
print('52g protocol and hypotheses written')
